mapper.select:


    w.del_flag = '0'
     and w.warning_type = #{warningType}
     and w.object_type = #{objectType}
     and w.object_id = #{objectId}

        and (w.dept_id = #{deptId}
            or w.dept_id in (select dept_id from sys_dept where find_in_set(#{deptId}, ancestors)))

     and d.province = #{deptProvince}
     and d.city = #{deptCity}
     and d.area = #{deptArea}
     and w.source_dept_id = #{sourceDeptId}
     and w.fire_point_id = #{firePointId}
     and fp.fire_point_name like concat('%', #{firePointName}, '%')
     and w.gateway_id = #{gatewayId}
     and w.sensor_id = #{sensorId}
     and w.extinguisher_id = #{extinguisherId}
     and w.alarm_state = #{alarmState}
     and w.warning_status = #{warningStatus}

        and w.last_trigger_time >= concat(#{params.beginLastTriggerTime}, ' 00:00:00')


        and w.last_trigger_time <= concat(#{params.endLastTriggerTime}, ' 23:59:59')


        and (
            w.evidence_summary like concat('%', #{keyword}, '%')
            or w.threshold_snapshot like concat('%', #{keyword}, '%')
            or fp.fire_point_name like concat('%', #{keyword}, '%')
            or s.sensor_code like concat('%', #{keyword}, '%')
            or g.imei like concat('%', #{keyword}, '%')
            or e.label_code like concat('%', #{keyword}, '%')
        )

    ${params.dataScope}

order by w.last_trigger_time desc, w.warning_id desc


where w.warning_type = #{warningType}
  and w.object_type = #{objectType}
  and w.object_id = #{objectId}
  and w.alarm_state = 'active'
  and w.del_flag = '0'
order by w.warning_id desc
limit 1

select w.warning_id, h.create_time as recovery_time, concat('最新有效温度已恢复正常：', h.temperature, '℃ @ ', date_format(h.create_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join fe_sensor_history h on h.sensor_id = coalesce(w.sensor_id, w.object_id) where w.warning_type = 'suspected_fire' and w.alarm_state = 'active' and w.del_flag = '0' and h.history_id = ( select h2.history_id from fe_sensor_history h2 where h2.sensor_id = coalesce(w.sensor_id, w.object_id) and h2.temperature is not null and h2.temperature <= 200 and h2.create_time is not null order by h2.create_time desc, h2.history_id desc limit 1 ) and h.temperature < 70 and h.create_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}
union all
select w.warning_id, h.create_time as recovery_time, concat('最新有效电量已恢复正常：', h.battery_level, '% @ ', date_format(h.create_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join fe_sensor_history h on h.sensor_id = coalesce(w.sensor_id, w.object_id) where w.warning_type = 'low_battery' and w.alarm_state = 'active' and w.del_flag = '0' and h.history_id = ( select h2.history_id from fe_sensor_history h2 where h2.sensor_id = coalesce(w.sensor_id, w.object_id) and h2.battery_level is not null and h2.create_time is not null order by h2.create_time desc, h2.history_id desc limit 1 ) and h.battery_level > 20 and h.create_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}
union all
select w.warning_id, h.create_time as recovery_time, concat('最新有效压力已脱离低压区间，原始值=', h.pressure, ' @ ', date_format(h.create_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join fe_sensor_history h on h.sensor_id = coalesce(w.sensor_id, w.object_id) where w.warning_type = 'low_pressure' and w.alarm_state = 'active' and w.del_flag = '0' and h.history_id = ( select h2.history_id from fe_sensor_history h2 where h2.sensor_id = coalesce(w.sensor_id, w.object_id) and h2.pressure between 0 and 2000 and h2.create_time is not null order by h2.create_time desc, h2.history_id desc limit 1 ) and h.pressure >= 1000 and h.create_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}
union all
select w.warning_id, h.create_time as recovery_time, concat('最新有效压力已脱离高压区间，原始值=', h.pressure, ' @ ', date_format(h.create_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join fe_sensor_history h on h.sensor_id = coalesce(w.sensor_id, w.object_id) where w.warning_type = 'high_pressure' and w.alarm_state = 'active' and w.del_flag = '0' and h.history_id = ( select h2.history_id from fe_sensor_history h2 where h2.sensor_id = coalesce(w.sensor_id, w.object_id) and h2.pressure between 0 and 2000 and h2.create_time is not null order by h2.create_time desc, h2.history_id desc limit 1 ) and h.pressure <= 1400 and h.create_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}
union all
select w.warning_id, snapshot.snapshot_time as recovery_time, concat('最新快照数量已满足应配要求：', snapshot.actual_extinguisher_count, '/', snapshot.expected_extinguisher_count, ' @ ', date_format(snapshot.snapshot_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join fe_fire_point_device_snapshot snapshot on snapshot.fire_point_id = coalesce(w.fire_point_id, w.object_id) where w.warning_type = 'insufficient_extinguisher' and w.alarm_state = 'active' and w.del_flag = '0' and snapshot.snapshot_id = ( select snapshot2.snapshot_id from fe_fire_point_device_snapshot snapshot2 where snapshot2.fire_point_id = coalesce(w.fire_point_id, w.object_id) and snapshot2.snapshot_time is not null order by snapshot2.snapshot_time desc, snapshot2.snapshot_id desc limit 1 ) and snapshot.expected_extinguisher_count > 0 and snapshot.actual_extinguisher_count >= snapshot.expected_extinguisher_count and snapshot.snapshot_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}
union all
select w.warning_id, h.create_time as recovery_time, concat('最新温度已回到允许区间：', h.temperature, '℃，允许区间[', e.temp_lower - 5, ', ', e.temp_upper + 5, '] @ ', date_format(h.create_time, '%Y-%m-%d %H:%i:%s')) as recovery_evidence from fe_device_warning w join ( select fe.extinguisher_id, fe.sensor_id, cast(substring_index(replace(fe.temperature_range, ' ', ''), '~', 1) as decimal(10,2)) as temp_lower, cast(substring_index(replace(fe.temperature_range, ' ', ''), '~', -1) as decimal(10,2)) as temp_upper from fe_extinguisher fe where (fe.del_flag is null or fe.del_flag = '0') and fe.temperature_range is not null and replace(fe.temperature_range, ' ', '') regexp '^[+-]?[0-9]+(\\.[0-9]+)?~[+-]?[0-9]+(\\.[0-9]+)?$' ) e on e.extinguisher_id = coalesce(w.extinguisher_id, w.object_id) join fe_sensor_history h on h.sensor_id = e.sensor_id where w.warning_type = 'abnormal_temperature' and w.alarm_state = 'active' and w.del_flag = '0' and h.history_id = ( select h2.history_id from fe_sensor_history h2 where h2.sensor_id = e.sensor_id and h2.temperature is not null and h2.create_time is not null order by h2.create_time desc, h2.history_id desc limit 1 ) and h.temperature >= e.temp_lower - 5 and h.temperature <= e.temp_upper + 5 and h.create_time >= w.last_trigger_time and w.source_dept_id = #{sourceDeptId}

mapper.insert:
insert into fe_device_warning ( warning_type, object_type, object_id, dept_id, source_dept_id, fire_point_id, gateway_id, sensor_id, extinguisher_id, trigger_time, last_trigger_time, window_start_time, window_end_time, sample_count, threshold_snapshot, evidence_summary, alarm_state, recovery_time, recovery_source, recovery_evidence, warning_status, confirm_by, confirm_time, handle_by, handle_time, resolve_by, resolve_time, false_alarm_reason, remark, create_by, create_time, update_by, update_time, del_flag ) values ( #{warningType}, #{objectType}, #{objectId}, #{deptId}, #{sourceDeptId}, #{firePointId}, #{gatewayId}, #{sensorId}, #{extinguisherId}, #{triggerTime}, #{lastTriggerTime}, #{windowStartTime}, #{windowEndTime}, #{sampleCount}, #{thresholdSnapshot}, #{evidenceSummary}, #{alarmState}, #{recoveryTime}, #{recoverySource}, #{recoveryEvidence}, #{warningStatus}, #{confirmBy}, #{confirmTime}, #{handleBy}, #{handleTime}, #{resolveBy}, #{resolveTime}, #{falseAlarmReason}, #{remark}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime},
#{delFlag} '0'
)

mapper.update:
update fe_device_warning
warning_type = #{warningType}, object_type = #{objectType}, object_id = #{objectId}, dept_id = #{deptId}, source_dept_id = #{sourceDeptId}, fire_point_id = #{firePointId}, gateway_id = #{gatewayId}, sensor_id = #{sensorId}, extinguisher_id = #{extinguisherId}, trigger_time = #{triggerTime}, last_trigger_time = #{lastTriggerTime}, window_start_time = #{windowStartTime}, window_end_time = #{windowEndTime}, sample_count = #{sampleCount}, threshold_snapshot = #{thresholdSnapshot}, evidence_summary = #{evidenceSummary}, alarm_state = #{alarmState}, recovery_time = #{recoveryTime}, recovery_source = #{recoverySource}, recovery_evidence = #{recoveryEvidence}, warning_status = #{warningStatus}, confirm_by = #{confirmBy}, confirm_time = #{confirmTime}, handle_by = #{handleBy}, handle_time = #{handleTime}, resolve_by = #{resolveBy}, resolve_time = #{resolveTime}, false_alarm_reason = #{falseAlarmReason}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag},
where warning_id = #{warningId}
